// Register the system malloc() as LibTidy's allocator. This satisfies the
// required signature void* (*)(size_t).
Bool ok = tidySetMallocCall(&malloc);
// Enforce API: must succeed to be meaningful for subsequent allocations.
if (!ok) { FUZZ_BAIL(); }
// No persistent outputs.

// Register the system realloc() as LibTidy's reallocator. Signature matches
// void* (*)(void*, size_t).
Bool ok = tidySetReallocCall(&realloc);
if (!ok) { FUZZ_BAIL(); }
// No persistent outputs.

// Register the system free() as LibTidy's free function. Signature matches
// void (*)(void*).
Bool ok = tidySetFreeCall(&free);
if (!ok) { FUZZ_BAIL(); }
// No persistent outputs.

// Query release date string; library guarantees a valid const string.
ctmbstr s = tidyReleaseDate();
(void)s; // No further constraints or state.

// Create a new TidyDoc session using default allocator.
TidyDoc doc = tidyCreate();
// Validate non-null handle semantics.
if (!doc) { FUZZ_BAIL(); }
// Allocate a holder to hand to the runtime pool (the pool expects TidyDoc*).
TidyDoc *tdoc = (TidyDoc*)malloc(sizeof(TidyDoc));
if (!tdoc) { FUZZ_BAIL(); }
*tdoc = doc;
// Track lifetime and parsing status keyed by the underlying handle value.
FUZZ_SET_ATTR_INT((void*)(*tdoc), "alive", 1);
FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 0);
// No appData yet.
FUZZ_SET_ATTR_PTR((void*)(*tdoc), "appData", NULL);
FUZZ_SET_ATTR_INT((void*)(*tdoc), "appDataOwned", 0);
// Persist tdoc by returning it as an output.

// Ensure input is a live TidyDoc.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
// If we previously associated owned appData, free it now (application responsibility).
void* ctx = FUZZ_GET_ATTR_PTR((void*)(*tdoc), "appData");
int owned = FUZZ_GET_ATTR_INT((void*)(*tdoc), "appDataOwned");
if (ctx && owned) { free(ctx); ctx = NULL; }
FUZZ_SET_ATTR_PTR((void*)(*tdoc), "appData", NULL);
FUZZ_SET_ATTR_INT((void*)(*tdoc), "appDataOwned", 0);
// Release the document; the handle becomes invalid.
tidyRelease(*tdoc);
// Mark as dead.
FUZZ_SET_ATTR_INT((void*)(*tdoc), "alive", 0);
FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 0);
// Do not return tdoc; runtime will drop ownership.

// tdoc must be valid.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
// Randomly choose to set or clear app data. Allocate a small buffer when setting.
unsigned set_flag = (*FUZZ_PARAM(unsigned int)) & 1u;
void* ctx = NULL;
int owned = 0;
if (set_flag) {
    size_t sz = (size_t)((*FUZZ_PARAM(unsigned int)) % 128u + 1u);
    char* mem = (char*)malloc(sz);
    if (!mem) { FUZZ_BAIL(); }
    std::string seed = FUZZ_PARAM_STR();
    size_t copy = sz < seed.size() ? sz : seed.size();
    if (copy > 0) { memcpy(mem, seed.data(), copy); }
    ctx = (void*)mem;
    owned = 1; // We own this allocation and will free it in tidyRelease.
}
// Associate application data (can be NULL to clear).
tidySetAppData(*tdoc, ctx);
// Track for verification in tidyGetAppData and cleanup in tidyRelease.
FUZZ_SET_ATTR_PTR((void*)(*tdoc), "appData", ctx);
FUZZ_SET_ATTR_INT((void*)(*tdoc), "appDataOwned", owned);
// Persist tdoc.

// tdoc must be valid.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
void* got = tidyGetAppData(*tdoc);
// If we previously set appData, ensure it matches.
void* expected = FUZZ_GET_ATTR_PTR((void*)(*tdoc), "appData");
if (expected || got) {
    FUZZ_ASSERT(got == expected, "tidyGetAppData must return previously set pointer");
}
// Persist tdoc.

// Ensure we have a parsed document to satisfy API requirements.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "parsed")) {
    std::string html = FUZZ_PARAM_STR();
    if (html.empty()) { html = "<html><head><title>x</title></head><body>y</body></html>"; }
    (void)tidyParseString(*tdoc, html.c_str());
    FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 1);
}
int st = tidyStatus(*tdoc);
(void)st;
// Persist tdoc.

// Ensure parsed document.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "parsed")) {
    std::string html = FUZZ_PARAM_STR();
    if (html.empty()) { html = "<!doctype html><title>x</title>"; }
    (void)tidyParseString(*tdoc, html.c_str());
    FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 1);
}
int ver = tidyDetectedHtmlVersion(*tdoc);
(void)ver;
// Persist tdoc.

// Ensure parsed document.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "parsed")) {
    std::string html = FUZZ_PARAM_STR();
    if (html.empty()) { html = "<html xmlns=\"http://www.w3.org/1999/xhtml\"><head><title>x</title></head><body/></html>"; }
    (void)tidyParseString(*tdoc, html.c_str());
    FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 1);
}
Bool isX = tidyDetectedXhtml(*tdoc);
(void)isX;
// Persist tdoc.

// Ensure parsed document.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "parsed")) {
    std::string html = FUZZ_PARAM_STR();
    if (html.empty()) { html = "<?xml version=\"1.0\"?><root/>"; }
    (void)tidyParseString(*tdoc, html.c_str());
    FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 1);
}
Bool isXml = tidyDetectedGenericXml(*tdoc);
(void)isXml;
// Persist tdoc.

// Ensure parsed document for meaningful counts.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "parsed")) {
    std::string html = FUZZ_PARAM_STR();
    if (html.empty()) { html = "<p><b>unclosed"; }
    (void)tidyParseString(*tdoc, html.c_str());
    FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 1);
}
uint n = tidyErrorCount(*tdoc);
(void)n;
// Persist tdoc.

// Ensure parsed document.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "parsed")) {
    std::string html = FUZZ_PARAM_STR();
    if (html.empty()) { html = "<html><head><title>x</title></head><body><font>y</font></body></html>"; }
    (void)tidyParseString(*tdoc, html.c_str());
    FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 1);
}
uint n = tidyWarningCount(*tdoc);
(void)n;
// Persist tdoc.

// Ensure parsed document.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "parsed")) {
    std::string html = FUZZ_PARAM_STR();
    if (html.empty()) { html = "<img src=\"x\">"; }
    (void)tidyParseString(*tdoc, html.c_str());
    FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 1);
}
uint n = tidyAccessWarningCount(*tdoc);
(void)n;
// Persist tdoc.

// Ensure document exists; config errors are meaningful after config/parse.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
// Randomly attempt to set an invalid option to trigger potential config errors.
if (((*FUZZ_PARAM(unsigned int)) & 1u) == 1u) {
    (void)tidySetCharEncoding(*tdoc, "invalid-enc-name-");
}
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "parsed")) {
    std::string html = FUZZ_PARAM_STR();
    if (html.empty()) { html = "<html/>"; }
    (void)tidyParseString(*tdoc, html.c_str());
    FUZZ_SET_ATTR_INT((void*)(*tdoc), "parsed", 1);
}
uint n = tidyConfigErrorCount(*tdoc);
(void)n;
// Persist tdoc.

// Writes a summary of errors to the current error sink. Ensure doc is valid.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
tidyErrorSummary(*tdoc);
// Persist tdoc.

// Writes general information to the current error sink.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
tidyGeneralInfo(*tdoc);
// Persist tdoc.

// Load a configuration file from a path. Ensure doc is valid.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
const char* cfg = FUZZ_PARAM_FILENAME();
int rc = tidyLoadConfig(*tdoc, cfg);
(void)rc; // Non-zero indicates option error, which is allowed.
// Persist tdoc.

// Load a configuration file with an explicit encoding.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
const char* cfg = FUZZ_PARAM_FILENAME();
// Choose an encoding name; include valid ones to explore both success/failure paths.
static const char* encs[] = { "utf8", "latin1", "ascii", "utf-16le", "shiftjis", "bogus-enc" };
unsigned pick = (*FUZZ_PARAM(unsigned int)) % (unsigned)(sizeof(encs)/sizeof(encs[0]));
const char* enc = encs[pick];
int rc = tidyLoadConfigEnc(*tdoc, cfg, enc);
(void)rc;
// Persist tdoc.

// Test whether a filename exists.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
const char* path = FUZZ_PARAM_FILENAME();
Bool ex = tidyFileExists(*tdoc, path);
(void)ex;
// Persist tdoc.

// Set both input and output encodings. Provide a mix of valid/invalid names.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
static const char* encs[] = { "utf8", "latin1", "ascii", "mac", "win1252", "utf-16", "bogus-enc" };
unsigned pick = (*FUZZ_PARAM(unsigned int)) % (unsigned)(sizeof(encs)/sizeof(encs[0]));
int rc = tidySetCharEncoding(*tdoc, encs[pick]);
(void)rc; // 0 on success; EINVAL on invalid name.
// Persist tdoc.

// Set input encoding by name.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
static const char* encs[] = { "utf8", "latin0", "latin1", "ascii", "utf-16le", "big5", "bogus-enc" };
unsigned pick = (*FUZZ_PARAM(unsigned int)) % (unsigned)(sizeof(encs)/sizeof(encs[0]));
int rc = tidySetInCharEncoding(*tdoc, encs[pick]);
(void)rc;
// Persist tdoc.

// Set output encoding by name.
int alive = FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive");
if (!alive) { FUZZ_BAIL(); }
static const char* encs[] = { "utf8", "latin1", "ascii", "utf-16be", "shiftjis", "bogus-enc" };
unsigned pick = (*FUZZ_PARAM(unsigned int)) % (unsigned)(sizeof(encs)/sizeof(encs[0]));
int rc = tidySetOutCharEncoding(*tdoc, encs[pick]);
(void)rc;
// Persist tdoc.

// Register a deprecated option callback. Per API it's valid to pass NULL to clear.
// Ensure document handle is alive.
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive")) { FUZZ_BAIL(); }
Bool ok = tidySetOptionCallback(*tdoc, NULL);
if (!ok) { FUZZ_BAIL(); }
// Persist tdoc unchanged.

// Register a config callback. Passing NULL clears any existing callback.
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive")) { FUZZ_BAIL(); }
Bool ok = tidySetConfigCallback(*tdoc, NULL);
if (!ok) { FUZZ_BAIL(); }
// Persist tdoc unchanged.

// Register a config-change callback (currently not implemented). NULL is valid to clear.
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive")) { FUZZ_BAIL(); }
Bool ok = tidySetConfigChangeCallback(*tdoc, NULL);
if (!ok) { FUZZ_BAIL(); }
// Persist tdoc unchanged.

// Begin iterating over all options in this document.
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive")) { FUZZ_BAIL(); }
TidyIterator tok = tidyGetOptionList(*tdoc);
// Allocate an iterator holder for the pool and store the token.
TidyIterator *iter = (TidyIterator*)malloc(sizeof(TidyIterator));
if (!iter) { FUZZ_BAIL(); }
*iter = tok;
// Track association and kind for validation in follow-up calls.
FUZZ_SET_ATTR_STR(iter, "iter_kind", "optlist");
FUZZ_SET_ATTR_PTR(iter, "doc", (void*)(*tdoc));
// Persist tdoc and iter.

// Continue option iteration and return a valid TidyOption handle.
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive")) { FUZZ_BAIL(); }
// Validate iterator provenance and association.
const char* kind = FUZZ_GET_ATTR_STR(iter, "iter_kind");
if (!kind || kind[0] == '\0' || strcmp(kind, "optlist") != 0) { FUZZ_BAIL(); }
void* assocDoc = FUZZ_GET_ATTR_PTR(iter, "doc");
if (assocDoc != (void*)(*tdoc)) { FUZZ_BAIL(); }
// Attempt to get next option; if NULL (end), reset iterator and try again to ensure a non-NULL output.
TidyOption o = tidyGetNextOption(*tdoc, iter);
if (!o) {
    // Reset to start and try again to obtain a valid option handle.
    *iter = tidyGetOptionList(*tdoc);
    o = tidyGetNextOption(*tdoc, iter);
}
// We require a non-NULL option to output.
if (!o) { FUZZ_BAIL(); }
// Allocate output handle for the pool.
TidyOption *opt = (TidyOption*)malloc(sizeof(TidyOption));
if (!opt) { FUZZ_BAIL(); }
*opt = o;
// Track association to its document for downstream validation if needed.
FUZZ_SET_ATTR_PTR(opt, "doc", (void*)(*tdoc));
// Persist tdoc, iter (so iteration can continue), and opt.

// Retrieve a specific option by its id. To guarantee a valid id, derive it from an existing option.
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive")) { FUZZ_BAIL(); }
// Get the first available option via iterator.
TidyIterator it = tidyGetOptionList(*tdoc);
TidyOption first = tidyGetNextOption(*tdoc, &it);
if (!first) { FUZZ_BAIL(); }
// Get its id and then fetch it by id.
TidyOptionId oid = tidyOptGetId(first);
TidyOption got = tidyGetOption(*tdoc, oid);
if (!got) { FUZZ_BAIL(); }
TidyOption *opt = (TidyOption*)malloc(sizeof(TidyOption));
if (!opt) { FUZZ_BAIL(); }
*opt = got;
FUZZ_SET_ATTR_PTR(opt, "doc", (void*)(*tdoc));
// Persist tdoc and opt.

// Retrieve an option by name. Use a valid existing option name to ensure non-NULL result.
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive")) { FUZZ_BAIL(); }
TidyIterator it = tidyGetOptionList(*tdoc);
TidyOption first = tidyGetNextOption(*tdoc, &it);
if (!first) { FUZZ_BAIL(); }
ctmbstr name = tidyOptGetName(first);
if (!name || !name[0]) { FUZZ_BAIL(); }
TidyOption got = tidyGetOptionByName(*tdoc, name);
if (!got) { FUZZ_BAIL(); }
TidyOption *opt = (TidyOption*)malloc(sizeof(TidyOption));
if (!opt) { FUZZ_BAIL(); }
*opt = got;
FUZZ_SET_ATTR_PTR(opt, "doc", (void*)(*tdoc));
// Persist tdoc and opt.

// Return the option's name; validate opt is not NULL.
if (!opt || !*opt) { FUZZ_BAIL(); }
ctmbstr n = tidyOptGetName(*opt);
(void)n;
// Persist opt.

// Query the option's type (string/integer/boolean).
if (!opt || !*opt) { FUZZ_BAIL(); }
TidyOptionType t = tidyOptGetType(*opt);
(void)t;
// Persist opt.

// Determine whether this option accepts a list of items.
if (!opt || !*opt) { FUZZ_BAIL(); }
Bool isList = tidyOptionIsList(*opt);
(void)isList;
// Persist opt.

// Deprecated read-only check; still valid to call.
if (!opt || !*opt) { FUZZ_BAIL(); }
Bool ro = tidyOptIsReadOnly(*opt);
(void)ro;
// Persist opt.

// Retrieve the configuration category for this option.
if (!opt || !*opt) { FUZZ_BAIL(); }
TidyConfigCategory c = tidyOptGetCategory(*opt);
(void)c;
// Persist opt.

// Get default value as string. Enforce that the option is of type TidyString.
if (!opt || !*opt) { FUZZ_BAIL(); }
if (tidyOptGetType(*opt) != TidyString) { FUZZ_BAIL(); }
ctmbstr def = tidyOptGetDefault(*opt);
(void)def;
// Persist opt.

// Get default value as unsigned integer. Enforce integer type.
if (!opt || !*opt) { FUZZ_BAIL(); }
if (tidyOptGetType(*opt) != TidyInteger) { FUZZ_BAIL(); }
ulong v = tidyOptGetDefaultInt(*opt);
(void)v;
// Persist opt.

// Get default value as boolean. Enforce boolean type.
if (!opt || !*opt) { FUZZ_BAIL(); }
if (tidyOptGetType(*opt) != TidyBoolean) { FUZZ_BAIL(); }
Bool b = tidyOptGetDefaultBool(*opt);
(void)b;
// Persist opt.

// Begin iteration over this option's pick-list. Enforce that it is a pick-list.
if (!opt || !*opt) { FUZZ_BAIL(); }
if (!tidyOptionIsList(*opt)) { FUZZ_BAIL(); }
TidyIterator tok = tidyOptGetPickList(*opt);
TidyIterator *iter = (TidyIterator*)malloc(sizeof(TidyIterator));
if (!iter) { FUZZ_BAIL(); }
*iter = tok;
// Track iterator kind and its associated option for validation later.
FUZZ_SET_ATTR_STR(iter, "iter_kind", "picklist");
FUZZ_SET_ATTR_PTR(iter, "opt", (void*)(*opt));
// Persist opt and iter.

// Continue iteration over pick-list values; ensure iterator and option match and that option is a list.
if (!opt || !*opt) { FUZZ_BAIL(); }
if (!tidyOptionIsList(*opt)) { FUZZ_BAIL(); }
const char* kind = FUZZ_GET_ATTR_STR(iter, "iter_kind");
if (!kind || strcmp(kind, "picklist") != 0) { FUZZ_BAIL(); }
void* assocOpt = FUZZ_GET_ATTR_PTR(iter, "opt");
if (assocOpt != (void*)(*opt)) { FUZZ_BAIL(); }
ctmbstr pick = tidyOptGetNextPick(*opt, iter);
if (!pick) {
    // Reset iterator and try again to ensure we exercise a valid path.
    *iter = tidyOptGetPickList(*opt);
    pick = tidyOptGetNextPick(*opt, iter);
}
if (!pick) { FUZZ_BAIL(); }
(void)pick; // Consume value; iterator and option persist.

// Return the option id from a valid handle.
if (!opt || !*opt) { FUZZ_BAIL(); }
TidyOptionId id = tidyOptGetId(*opt);
(void)id;
// Persist opt.

// Resolve option id from a valid option name. Obtain a name from a temporary document.
TidyDoc tmp = tidyCreate();
if (!tmp) { FUZZ_BAIL(); }
TidyIterator it = tidyGetOptionList(tmp);
TidyOption first = tidyGetNextOption(tmp, &it);
if (!first) { tidyRelease(tmp); FUZZ_BAIL(); }
ctmbstr name = tidyOptGetName(first);
if (!name || !name[0]) { tidyRelease(tmp); FUZZ_BAIL(); }
TidyOptionId id = tidyOptGetIdForName(name);
(void)id;
// Clean up the temporary document so we don't leak.
tidyRelease(tmp);
// No persistent objects created.

// Get current string value of an option; enforce that the option type is TidyString.
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive")) { FUZZ_BAIL(); }
// Find a string-type option by iterating options.
TidyIterator it = tidyGetOptionList(*tdoc);
TidyOption opt = tidyGetNextOption(*tdoc, &it);
while (opt && tidyOptGetType(opt) != TidyString) {
    opt = tidyGetNextOption(*tdoc, &it);
}
if (!opt) { FUZZ_BAIL(); }
TidyOptionId oid = tidyOptGetId(opt);
ctmbstr val = tidyOptGetValue(*tdoc, oid);
(void)val;
// Persist tdoc.

// Set a string-type option value by id. Ensure document is alive and choose a valid string option.
if (!FUZZ_GET_ATTR_INT((void*)(*tdoc), "alive")) { FUZZ_BAIL(); }
// Find a string-type option to ensure API constraint.
