FUZZ_SET_ATTR_PTR(buf, "attached_ptr", nullptr);
FUZZ_SET_ATTR_INT(buf, "attached_size", 0);
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Ensure buf is prepared for allocation.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
// Construct a minimal, working custom allocator as required by the API.
TidyAllocatorVtbl vtbl = {};
vtbl.alloc   = +[](TidyAllocator* /*self*/, size_t n) -> void* { return malloc(n ? n : 1); };
vtbl.realloc = +[](TidyAllocator* /*self*/, void* block, size_t n) -> void* {
    if (!block) return malloc(n ? n : 1);
    return realloc(block, n ? n : 1);
};
vtbl.free    = +[](TidyAllocator* /*self*/, void* block) { if (block) free(block); };
vtbl.panic   = +[](TidyAllocator* /*self*/, const char* /*msg*/) { /* ignore in fuzzing */ };
TidyAllocator alloc = {};
alloc.vtbl = &vtbl;
uint allocSize = (uint)(*FUZZ_PARAM(unsigned int) % 2048u + 1u);
// Reallocate contents using the custom allocator.
tidyBufAllocWithAllocator(buf, &alloc, allocSize);
// Update bookkeeping; buffer now owns internal allocation via custom allocator.
FUZZ_SET_ATTR_INT(buf, "attached", 0);
FUZZ_SET_ATTR_PTR(buf, "attached_ptr", nullptr);
FUZZ_SET_ATTR_INT(buf, "attached_size", 0);
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Ensure buf is initialized per API contract.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
uint need = (uint)(*FUZZ_PARAM(unsigned int) % 2048u); // allow 0..2047
// Randomize chunk size; 0 requests default chunk size per API.
uint chunk = (uint)(*FUZZ_PARAM(unsigned int) % 5u == 0u ? 0u : (*FUZZ_PARAM(unsigned int) % 512u + 1u));
// Ensure capacity; this may grow the buffer.
tidyBufCheckAlloc(buf, need, chunk);
// Reading position/state may change; invalidate unget opportunity.
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// buf must be valid. If the buffer is attached to external memory, we must
// detach and free that memory since ownership is external per API docs.
if (FUZZ_GET_ATTR_INT(buf, "attached")) {
    void* p = FUZZ_GET_ATTR_PTR(buf, "attached_ptr");
    tidyBufDetach(buf);
    if (p) { free(p); }
    FUZZ_SET_ATTR_INT(buf, "attached", 0);
    FUZZ_SET_ATTR_PTR(buf, "attached_ptr", nullptr);
    FUZZ_SET_ATTR_INT(buf, "attached_size", 0);
}
// Free any internally owned contents.
tidyBufFree(buf);
// Buffer remains initialized but empty.
FUZZ_SET_ATTR_INT(buf, "initialized", 1);
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Clear all bytes in the buffer; requires initialized buffer.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
tidyBufClear(buf);
// After clearing bytes, previous read state is undefined; prevent unget.
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Attach external memory to buf. Requires initialized buffer and a backing
// allocation that remains valid after this stub returns.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
// If already attached, detach and free previous external memory to avoid leaks.
if (FUZZ_GET_ATTR_INT(buf, "attached")) {
    void* oldp = FUZZ_GET_ATTR_PTR(buf, "attached_ptr");
    tidyBufDetach(buf);
    if (oldp) { free(oldp); }
    FUZZ_SET_ATTR_INT(buf, "attached", 0);
    FUZZ_SET_ATTR_PTR(buf, "attached_ptr", nullptr);
    FUZZ_SET_ATTR_INT(buf, "attached_size", 0);
}
// Create an external memory block from fuzz data, limited in size.
std::string s = FUZZ_PARAM_STR();
size_t n = s.size();
if (n == 0) { FUZZ_BAIL(); }
if (n > 1024u) n = 1024u;
byte* ext = (byte*)malloc(n);
if (!ext) { FUZZ_BAIL(); }
memcpy(ext, s.data(), n);
// Attach external memory; ownership remains with caller (this stub/runtime).
tidyBufAttach(buf, ext, (uint)n);
// Record attachment so tidyBufDetach/tidyBufFree can release it later.
FUZZ_SET_ATTR_INT(buf, "attached", 1);
FUZZ_SET_ATTR_PTR(buf, "attached_ptr", ext);
FUZZ_SET_ATTR_INT(buf, "attached_size", (int)n);
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Detach from external memory; requires that buf is currently attached.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(buf, "attached")) { FUZZ_BAIL(); }
void* p = FUZZ_GET_ATTR_PTR(buf, "attached_ptr");
tidyBufDetach(buf);
// Caller (this stub) is now responsible for freeing the previously attached memory.
if (p) { free(p); }
FUZZ_SET_ATTR_INT(buf, "attached", 0);
FUZZ_SET_ATTR_PTR(buf, "attached_ptr", nullptr);
FUZZ_SET_ATTR_INT(buf, "attached_size", 0);
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Append data to the end of the buffer; requires initialized buffer.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
std::string s = FUZZ_PARAM_STR();
size_t n = s.size();
if (n == 0) { FUZZ_BAIL(); }
if (n > 512u) n = 512u; // keep appends small for fuzzer performance
// Append; note this may reallocate internal storage.
tidyBufAppend(buf, (void*)s.data(), (uint)n);
// After append, previous read/unget assumptions may not hold.
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Put a single byte to the buffer; requires initialized buffer.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
byte bv = (byte)(*FUZZ_PARAM(unsigned int) & 0xFFu);
tidyBufPutByte(buf, bv);
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Pop a byte from the end; requires initialized buffer. Behavior on empty is
// unspecified; we simply call and ignore negative results.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
int b = tidyBufPopByte(buf);
(void)b; // discard; callers should check, but here we exercise the API.
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Get one byte from the front; requires initialized buffer. If successful,
// allow subsequent tidyBufUngetByte by setting can_unget.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
int b = tidyBufGetByte(buf);
if (b >= 0) {
    FUZZ_SET_ATTR_INT(buf, "can_unget", 1);
} else {
    FUZZ_SET_ATTR_INT(buf, "can_unget", 0);
}

// Query whether input position is at end; requires initialized buffer.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
Bool atEnd = tidyBufEndOfInput(buf);
(void)atEnd; // Used for coverage only.

// Unget requires that there is space/state to unget at least one byte.
// We enforce this by requiring a prior successful Get that set can_unget.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(buf, "can_unget")) { FUZZ_BAIL(); }
byte bv = (byte)(*FUZZ_PARAM(unsigned int) & 0xFFu);
tidyBufUngetByte(buf, bv);
// After ungetting, disallow another unget until next successful get.
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);

// Initialize an input source to read from a buffer.
// buf must be initialized and must remain valid while inp is used.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
tidyInitInputBuffer(inp, buf);
// Track binding for potential downstream validation.
FUZZ_SET_ATTR_PTR(inp, "bound_buf", buf);

// Initialize an output sink to write into a buffer. Buffer must be initialized.
if (!FUZZ_GET_ATTR_INT(buf, "initialized")) { FUZZ_BAIL(); }
tidyInitOutputBuffer(outp, buf);
// Track binding for potential downstream validation.
FUZZ_SET_ATTR_PTR(outp, "bound_buf", buf);

// Construct a TidyInputSource with valid callbacks and persistent context.
// Allocate the source object to return to the pool.
TidyInputSource *source = (TidyInputSource*)malloc(sizeof(TidyInputSource));
if (!source) { FUZZ_BAIL(); }

// Create a persistent input context containing a heap buffer and indices.
struct SrcCtx { unsigned char *data; uint len; uint idx; };
std::string s = FUZZ_PARAM_STR();
if (s.size() == 0) { s = "<html><head><title>a</title></head><body>b</body></html>"; }
if (s.size() > 1024) { s.resize(1024); }
SrcCtx* ctx = (SrcCtx*)malloc(sizeof(SrcCtx));
if (!ctx) { free(source); FUZZ_BAIL(); }
ctx->len = (uint)s.size();
ctx->idx = 0u;
ctx->data = (unsigned char*)malloc(ctx->len ? ctx->len : 1u);
if (!ctx->data) { free(ctx); free(source); FUZZ_BAIL(); }
if (ctx->len) { memcpy(ctx->data, s.data(), ctx->len); }

// Define non-capturing callbacks matching tidy typedefs.
auto getByte = +[](void* p)->int {
    SrcCtx* c = (SrcCtx*)p;
    if (!c) return 0;
    if (c->idx >= c->len) return 0; // value ignored when eof() is true
    return (int)(unsigned int)c->data[c->idx++];
};
auto ungetByte = +[](void* p, unsigned char /*b*/)->void {
    SrcCtx* c = (SrcCtx*)p;
    if (c && c->idx > 0u) { c->idx--; }
};
auto isEOF = +[](void* p)->Bool {
    SrcCtx* c = (SrcCtx*)p;
    if (!c) return yes;
    return (c->idx >= c->len) ? yes : no;
};

// Initialize the source; API requires valid pointers for all callbacks.
Bool ok = tidyInitSource(source, (void*)ctx, getByte, ungetByte, isEOF);
if (!ok) { free(ctx->data); free(ctx); free(source); FUZZ_BAIL(); }

// Track context for downstream nodes; runtime owns `source` and should retain ctx.
FUZZ_SET_ATTR_PTR(source, "ctx_ptr", (void*)ctx);
FUZZ_SET_ATTR_INT(source, "initialized", 1);
FUZZ_SET_ATTR_STR(source, "kind", "custom");
// Validation: ensured non-null source, persistent context, and valid callbacks; returning initialized source.

// Construct a TidyOutputSink with a valid putByte callback and persistent context.
TidyOutputSink *sink = (TidyOutputSink*)malloc(sizeof(TidyOutputSink));
if (!sink) { FUZZ_BAIL(); }

// Persistent sink context to collect bytes.
struct SinkCtx { unsigned char* buf; uint cap; uint sz; };
SinkCtx* ctx = (SinkCtx*)malloc(sizeof(SinkCtx));
if (!ctx) { free(sink); FUZZ_BAIL(); }
ctx->cap = 1024u; ctx->sz = 0u; ctx->buf = (unsigned char*)malloc(ctx->cap);
if (!ctx->buf) { free(ctx); free(sink); FUZZ_BAIL(); }

// putByte callback per API typedef.
auto putByte = +[](void* p, unsigned char b)->void {
    SinkCtx* c = (SinkCtx*)p;
    if (!c) return;
    if (c->sz < c->cap) { c->buf[c->sz++] = b; }
};

Bool ok = tidyInitSink(sink, (void*)ctx, putByte);
if (!ok) { free(ctx->buf); free(ctx); free(sink); FUZZ_BAIL(); }

// Track context so future stubs can validate/consume or free.
FUZZ_SET_ATTR_PTR(sink, "ctx_ptr", (void*)ctx);
FUZZ_SET_ATTR_INT(sink, "initialized", 1);
FUZZ_SET_ATTR_STR(sink, "kind", "buffered");
// Validation: created sink with correct callback and persistent storage; returning initialized sink.

// Allocate a TidyBuffer and initialize it with the default allocator.
TidyBuffer *buf = (TidyBuffer*)malloc(sizeof(TidyBuffer));
if (!buf) { FUZZ_BAIL(); }
// Initialize to a valid empty state per API.
tidyBufInit(buf);
// Track state for other stubs that expect these attributes.
FUZZ_SET_ATTR_INT(buf, "initialized", 1);
FUZZ_SET_ATTR_INT(buf, "buf_init", 1);
FUZZ_SET_ATTR_INT(buf, "attached", 0);
FUZZ_SET_ATTR_PTR(buf, "attached_ptr", nullptr);
FUZZ_SET_ATTR_INT(buf, "attached_size", 0);
FUZZ_SET_ATTR_INT(buf, "can_unget", 0);
// Validation: ensured heap-allocated buffer and proper tidy initialization; returning ready-to-use buffer.

