import random
import string
from typing import List, Tuple

# This generator produces valid, interesting HTML/XHTML/XML strings tailored to
# exercise the provided fuzzing stubs, which primarily call tidyParseString and
# related parsing APIs. We focus on diverse doctypes, namespaces, encodings,
# and constructs that can affect detected HTML version, XHTML, generic XML, and
# error/warning counts.

MAX_BYTES = 4096

HTML5_DOCTYPE = "<!doctype html>"
XHTML_NS = "http://www.w3.org/1999/xhtml"
SVG_NS = "http://www.w3.org/2000/svg"
MATHML_NS = "http://www.w3.org/1998/Math/MathML"

# Representative encodings labels Tidy recognizes (as names, content remains bytes)
ENCODING_NAMES = [
    "ascii", "latin0", "latin1", "utf8", "utf-8", "utf16", "utf-16",
    "utf16le", "utf16be", "mac", "win1252", "ibm858", "shiftjis", "big5"
]

# A few HTML fragments designed to trigger warnings/errors/accessibility notices
WARNING_TRIGGERS = [
    "<font color=red>deprecated</font>",
    "<center>centered</center>",
    "<img src=\"x.png\">",                 # missing alt => accessibility warning
    "<table><tr><td>no headers</td></tr></table>",
    "<p><b>unclosed",                         # unclosed tag => error
    "<script>var a = 1</script>",
    "<a name=\"old\">legacy anchor</a>",
]

# Some attribute edge cases
ATTR_CASES = [
    "class=foo",
    "data-x=\"1 2 3\"",
    "id='i'",
    "style=\"color:blue;\"",
    "hidden",
    "download",
    "async",
]

# Build different document shells to exercise tidyDetectedHtmlVersion and modes

def html5_doc(body: str) -> str:
    return f"{HTML5_DOCTYPE}<html><head><meta charset=\"utf-8\"><title>T</title></head><body>{body}</body></html>"


def transitional_html_doc(body: str) -> str:
    # Older doctype to influence version detection
    dt = "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" \"http://www.w3.org/TR/html4/loose.dtd\">"
    return f"{dt}<html><head><title>T</title></head><body>{body}</body></html>"


def xhtml_doc(body: str) -> str:
    dt = "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">"
    return f"{dt}<html xmlns=\"{XHTML_NS}\"><head><title>T</title></head><body>{body}</body></html>"


def generic_xml_doc(root: str) -> str:
    return f"<?xml version=\"1.0\" encoding=\"utf-8\"?>{root}"


def with_svg() -> str:
    return (
        f"<svg xmlns=\"{SVG_NS}\" viewBox=\"0 0 10 10\"><circle cx=\"5\" cy=\"5\" r=\"4\"/></svg>"
    )


def with_mathml() -> str:
    return (
        f"<math xmlns=\"{MATHML_NS}\"><mrow><mi>a</mi><mo>+</mo><mi>b</mi></mrow></math>"
    )


def random_attrs(rng: random.Random, k: int) -> str:
    parts = []
    for _ in range(k):
        parts.append(rng.choice(ATTR_CASES))
    return " ".join(parts)


def random_text(rng: random.Random, length: int) -> str:
    alphabet = string.ascii_letters + string.digits + " .,:;!?-_""'()[]{}"
    return ''.join(rng.choice(alphabet) for _ in range(length))


def mix_body(rng: random.Random) -> str:
    # Compose a body with a variety of elements that may cause warnings/errors
    chunks: List[str] = []

    # Headings and lists
    chunks.append("<h1>H</h1><ul><li>A</li><li>B</li></ul>")

    # Deprecated and proprietary-ish tags
    chunks.append(rng.choice(WARNING_TRIGGERS))

    # Forms and inputs
    chunks.append("<form method=\"get\" action=\"/\"><input type=\"text\" name=\"q\"></form>")

    # Table
    chunks.append("<table><thead><tr><th>H</th></tr></thead><tbody><tr><td>D</td></tr></tbody></table>")

    # Script/style blocks
    chunks.append("<style>body{margin:0}</style>")
    chunks.append("<script type=\"text/javascript\">/*x*/</script>")

    # Media with srcset/sources
    chunks.append("<picture><source srcset=\"a1.png 1x, a2.png 2x\"><img src=\"a1.png\" alt=\"t\"></picture>")

    # SVG/MathML occasionally
    if rng.random() < 0.5:
        chunks.append(with_svg())
    if rng.random() < 0.5:
        chunks.append(with_mathml())

    # Random paragraphs with attributes
    for _ in range(rng.randint(1, 3)):
        attrs = random_attrs(rng, rng.randint(0, 3))
        attrs = (" " + attrs) if attrs else ""
        chunks.append(f"<p{attrs}>{random_text(rng, rng.randint(5, 20))}</p>")

    return "".join(chunks)


def make_html_variant(rng: random.Random) -> str:
    body = mix_body(rng)
    variant = rng.choice(["html5", "transitional", "xhtml"])
    if variant == "html5":
        return html5_doc(body)
    elif variant == "transitional":
        return transitional_html_doc(body)
    else:
        return xhtml_doc(body)


def make_xml_variant(rng: random.Random) -> str:
    # Build a simple XML tree with attributes and nested elements
    attrs = []
    attrs.append(f"lang=\"en\"")
    if rng.random() < 0.5:
        attrs.append(f"encoding=\"{rng.choice(ENCODING_NAMES)}\"")
    if rng.random() < 0.5:
        attrs.append("version=\"1.0\"")
    a = " ".join(attrs)
    payload = random_text(rng, rng.randint(5, 20))
    nested = f"<child id=\"c1\"><sub>{payload}</sub></child>"
    # Occasionally include an empty element and CDATA-like text that remains plain
    extra = "" if rng.random() < 0.5 else "<empty/>"
    return generic_xml_doc(f"<root {a}>{nested}{extra}</root>")


def choose_document(rng: random.Random) -> str:
    # Prioritize HTML since most stubs call tidyParseString expecting HTML,
    # but include XHTML and generic XML to exercise detection APIs.
    choice = rng.choices(
        population=["html", "xhtml", "xml"],
        weights=[0.6, 0.25, 0.15],
        k=1,
    )[0]
    if choice == "html":
        return make_html_variant(rng)
    elif choice == "xhtml":
        # Force XHTML to help tidyDetectedXhtml()
        body = mix_body(rng)
        return xhtml_doc(body)
    else:
        return make_xml_variant(rng)


def clamp_bytes(b: bytes) -> bytes:
    if len(b) > MAX_BYTES:
        return b[:MAX_BYTES]
    return b


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Optionally prepend a XML declaration or charset meta to steer encodings
    doc = choose_document(rng)

    # Occasionally add meta charset variations or custom tags to exercise config
    extras: List[str] = []
    if rng.random() < 0.35 and doc.lower().startswith("<!doctype html>"):
        extras.append(f"<meta charset=\"{rng.choice(['utf-8','utf-16','windows-1252'])}\">")
    if rng.random() < 0.3:
        # Custom tag to influence custom tag handling
        extras.append("<x-custom data-a=\"1\" />")
    if rng.random() < 0.25:
        # Duplicate attributes scenario to exercise duplicate handling
        extras.append("<div class=\"a\" class=\"b\">dup</div>")

    # If XHTML, ensure self-closing variants appear
    if "xmlns=\"%s\"" % XHTML_NS in doc:
        extras.append("<br />")
        extras.append("<hr />")

    # Place extras near body end if possible
    if "</body>" in doc:
        doc = doc.replace("</body>", "".join(extras) + "</body>")
    else:
        doc += "".join(extras)

    b = doc.encode("utf-8", errors="strict")
    return clamp_bytes(b)

import random
import string
from typing import List

# This generator produces interesting, valid arbitrary strings for LibTidy option
# values. The target fuzz stubs call FUZZ_PARAM_STR() to provide strings for
# tidyOptSetValue (string-typed options only) and tidyOptParseValue (any option
# by name). Tidy will validate and parse according to the selected option.
#
# Strategy:
# - Provide a diverse corpus of plausible option values covering
#   - booleans (yes/no, true/false, on/off, 0/1)
#   - integers and ranges (including extremes and typical sizes)
#   - enumerations/picks common to Tidy (encodings, doctypes, newline modes, etc.)
#   - lists and comma/space separated values (for list-type options)
#   - file paths and URIs (for options that expect filenames or URLs)
#   - strings with whitespace, quotes, and escape-like sequences
#   - UTF-8 with non-ASCII characters
# - Randomly choose and sometimes compose values to keep variety while remaining
#   likely valid for many options.
# - Keep outputs under 4096 bytes.

_BOOL_STRS = [
    "yes", "no", "true", "false", "on", "off", "1", "0",
    "YeS", "nO"
]

_INT_STRS = [
    "0", "1", "2", "3", "4", "5", "8", "10", "16", "32", "64",
    "72", "80", "100", "120", "132", "256", "512", "1000", "4096"
]

# Common encodings known to Tidy
_ENCODINGS = [
    "raw", "ascii", "latin0", "latin1", "utf8", "utf-8",
    "mac", "win1252", "ibm858", "utf16le", "utf16be", "utf16",
    "big5", "shiftjis"
]

# Doctype modes and related strings
_DOCTYPES = [
    "html5", "omit", "auto", "strict", "loose", "user"
]

# Newline modes
_NEWLINES = ["LF", "CRLF", "CR", "lf", "crlf", "cr"]

# Duplicate attribute modes
_DUP_ATTR = ["keep-first", "keep-last", "keepfirst", "keeplast"]

# Attribute sort
_ATTR_SORT = ["none", "alpha", "alphabetical"]

# Uppercase policy
_UPPERCASE = ["no", "yes", "preserve"]

# Use custom tags
_CUSTOM_TAGS = ["no", "blocklevel", "empty", "inline", "pre"]

# Popular option names often expecting list(s). Even if the stub chooses the actual
# option independently, supplying compatible-looking values increases success rate.
# Values are examples, not guaranteed exhaustive/accurate; Tidy will validate.
_TAG_LIST_SAMPLES = [
    "a,b,span,div", "pre,code,samp", "section,article,aside",
    "img,br,hr,wbr", "p,ul,ol,li", "custom1,custom2"
]

# Priority attributes examples
_ATTR_LIST_SAMPLES = [
    "id,class,style", "href,src,alt", "type,rel,media",
    "width,height", "data-foo,data-bar"
]

# Filenames and paths
_PATHS = [
    "output.html", "errors.txt", "config.tidy", "tidy.conf",
    "../relative/path/file.html", "/tmp/tidy.out", "C:/temp/tidy.log",
    "./index.html"
]

# URIs
_URIS = [
    "http://example.com/", "https://example.org/page",
    "file:///tmp/input.html"
]

# Mute/report message keys examples (not exhaustive). Using generic-looking keys.
_MSG_KEYS = [
    "missing-end-tag", "discarding-unexpected", "trim-empty-element",
    "doctype-given", "encoding-mismatch", "attributes-sorted"
]

# Generic textual samples with whitespace and punctuation
_TEXT_SAMPLES = [
    "",  # sometimes empty is allowed; the stub guards empties, but we keep for mix
    "x", "   x", "x   ", "x y z", "Hello, world!",
    "name=value", "name: value", "name=value1,value2",
    "one,two,three", "one two three", "\tindented\ntext\r\n",
    '"quoted value"', "'single quoted'",
]

# UTF-8 samples
_UTF8_SAMPLES = [
    "café", "naïve", "日本語", "русский", "😀", "αβγ", "Résumé",
]

# Options that expect specific words
_SPECIFIC_VALUES: List[str] = (
    _ENCODINGS + _DOCTYPES + _NEWLINES + _DUP_ATTR + _ATTR_SORT +
    _UPPERCASE + _CUSTOM_TAGS
)

# Build some compound list values
def _random_list(rng: random.Random, items: List[str], min_n=2, max_n=5, sep=","):
    n = rng.randint(min_n, max_n)
    picks = rng.sample(items, k=min(n, len(items)))
    return sep.join(picks)

# Random ascii safe string
def _rand_ascii(rng: random.Random, min_len=1, max_len=64):
    length = rng.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + "-_.,:/ "+"\t\n"
    s = ''.join(rng.choice(alphabet) for _ in range(length))
    # Ensure reasonable probability of being non-empty printable segment
    return s.strip("\x00")

# Compose an interesting value based on buckets
def _choose_value(rng: random.Random) -> str:
    bucket = rng.choices(
        population=[
            "bool", "int", "encoding", "doctype", "newline", "dupattr",
            "attrsort", "uppercase", "customtags", "taglist", "attrlist",
            "path", "uri", "msgkey", "text", "utf8", "numberlist",
            "kvpairs", "randomascii"
        ],
        weights=[
            8, 8, 6, 5, 4, 3,
            3, 3, 3, 6, 5,
            4, 3, 2, 8, 4, 4,
            5, 6
        ],
        k=1
    )[0]

    if bucket == "bool":
        return rng.choice(_BOOL_STRS)
    if bucket == "int":
        return rng.choice(_INT_STRS)
    if bucket == "encoding":
        return rng.choice(_ENCODINGS)
    if bucket == "doctype":
        return rng.choice(_DOCTYPES)
    if bucket == "newline":
        return rng.choice(_NEWLINES)
    if bucket == "dupattr":
        return rng.choice(_DUP_ATTR)
    if bucket == "attrsort":
        return rng.choice(_ATTR_SORT)
    if bucket == "uppercase":
        return rng.choice(_UPPERCASE)
    if bucket == "customtags":
        return rng.choice(_CUSTOM_TAGS)
    if bucket == "taglist":
        # Some options accept space or comma separated; vary separators
        if rng.random() < 0.5:
            return rng.choice(_TAG_LIST_SAMPLES)
        return _random_list(rng, ["a","b","i","em","strong","div","span","pre","code","section","article","aside","main"], sep="," if rng.random()<0.5 else " ")
    if bucket == "attrlist":
        if rng.random() < 0.6:
            return rng.choice(_ATTR_LIST_SAMPLES)
        return _random_list(rng, ["id","class","style","href","src","alt","type","rel","media","lang","width","height"], sep="," if rng.random()<0.5 else " ")
    if bucket == "path":
        return rng.choice(_PATHS)
    if bucket == "uri":
        return rng.choice(_URIS)
    if bucket == "msgkey":
        return rng.choice(_MSG_KEYS)
    if bucket == "text":
        return rng.choice(_TEXT_SAMPLES)
    if bucket == "utf8":
        return rng.choice(_UTF8_SAMPLES)
    if bucket == "numberlist":
        # e.g., wrap length or numeric lists
        nums = [str(rng.choice([0,1,2,3,4,5,8,10,40,72,80,100,120,132])) for _ in range(rng.randint(2,5))]
        return ("," if rng.random()<0.5 else " ").join(nums)
    if bucket == "kvpairs":
        # Common key=value style often accepted by options that parse lists
        keys = ["indent", "wrap", "tab-size", "quote-marks", "numeric-entities", "newline"]
        values = [rng.choice(_INT_STRS + _BOOL_STRS + _SPECIFIC_VALUES)]
        if rng.random() < 0.5:
            # multi pairs
            n = rng.randint(2,4)
            pairs = []
            for _ in range(n):
                k = rng.choice(keys)
                v = rng.choice(_INT_STRS + _BOOL_STRS + _SPECIFIC_VALUES)
                pairs.append(f"{k}={v}")
            return ",".join(pairs)
        else:
            return f"{rng.choice(keys)}={rng.choice(_INT_STRS + _BOOL_STRS + _SPECIFIC_VALUES)}"
    if bucket == "randomascii":
        return _rand_ascii(rng)
    # fallback
    return "x"

# Some options expect multiple items; sometimes create combined strings
def _maybe_combine(rng: random.Random, base: str) -> str:
    if rng.random() < 0.25:
        # Append a comment-like fragment or whitespace padding
        suffix = rng.choice(["", " ", "  ", "\n", " # note", " ; comment"])
        return base + suffix
    if rng.random() < 0.25:
        # Combine two values separated by comma or space
        sep = "," if rng.random() < 0.6 else " "
        return base + sep + _choose_value(rng)
    return base


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly choose how many segments to compose; usually 1
    segments = 1
    if rng.random() < 0.20:
        segments = rng.randint(2, 4)
    parts: List[str] = []
    for _ in range(segments):
        val = _choose_value(rng)
        val = _maybe_combine(rng, val)
        parts.append(val)
    # Join parts with newline to allow multi-line config-like strings, which are
    # often acceptable for parse-by-name contexts.
    s = "\n".join(parts)
    # Ensure non-empty because one stub substitutes "x" if empty, but we provide
    # something meaningful here.
    if not s:
        s = "x"
    # Limit to 4096 bytes
    b = s.encode('utf-8', errors='strict')[:4096]
    # Guarantee not zero-length after truncation
    if not b:
        b = b"x"
    return b
